#[test]
fn golden_vectors_have_the_documented_shapes() {
    assert_eq!(CMP_GOLDEN_INPUT.len(), 48);
    assert_eq!(CMP_GOLDEN_OUTPUT.len(), CMP_GOLDEN_INPUT.len());
    assert_eq!(CMP_GOLDEN_CONTEXT.len(), 26);
    assert_eq!(CMP_GOLDEN_CONTEXT_IN.len(), 26);
    // the input is not silent and the compressor changed it
    assert!(CMP_GOLDEN_INPUT != CMP_GOLDEN_OUTPUT);
}
